name: Wizard CI Trigger

on:
  pull_request:
    types: [opened]
  issue_comment:
    types: [created]
  workflow_dispatch:
    inputs:
      pr_number:
        description: 'Pull request number to post the hint comment on'
        required: true
        type: number

permissions:
  contents: read
  issues: write
  pull-requests: write

jobs:
  # ============================================================================
  # POST WELCOME: First-time hint with all available apps
  # ============================================================================
  post-welcome:
    if: github.event_name == 'pull_request' || github.event_name == 'workflow_dispatch'
    runs-on: ubuntu-latest
    steps:
      - name: Fetch available apps from wizard-workbench
        id: fetch-apps
        run: |
          # Fetch app categories from wizard-workbench repo
          CATEGORIES=$(curl -s "https://api.github.com/repos/PostHog/wizard-workbench/contents/apps" \
            -H "Accept: application/vnd.github.v3+json" \
            | jq -r '[.[] | select(.type == "dir") | .name] | sort | .[]')

          # Only advertise directories whose workflow is CI-capable (apps/manifest.json).
          # Left empty on fetch failure, in which case no filtering is applied.
          CI_CAPABLE=$(curl -s "https://api.github.com/repos/PostHog/wizard-workbench/contents/apps/manifest.json" \
            -H "Accept: application/vnd.github.raw" \
            | jq -r '[.workflows[] | select(.ciCapable == true) | .dir] | .[]' 2>/dev/null || echo "")

          # Build lists by category
          CATEGORY_LIST=""
          APP_LIST_VISIBLE=""
          APP_LIST_COLLAPSED=""
          APP_COUNT=0
          VISIBLE_COUNT=3

          for category in $CATEGORIES; do
            # Skip directories the manifest marks as not CI-capable.
            if [ -n "$CI_CAPABLE" ] && ! echo "$CI_CAPABLE" | grep -qxF "$category"; then
              continue
            fi

            # Fetch apps in this category
            APPS=$(curl -s "https://api.github.com/repos/PostHog/wizard-workbench/contents/apps/$category" \
              -H "Accept: application/vnd.github.v3+json" \
              | jq -r '[.[] | select(.type == "dir") | .name] | sort | .[]' 2>/dev/null || echo "")

            if [ -n "$APPS" ]; then
              # Add to category list
              CATEGORY_LIST="$CATEGORY_LIST- \`/wizard-ci $category\`\n"

              # Add apps to visible or collapsed list
              for app in $APPS; do
                if [ $APP_COUNT -lt $VISIBLE_COUNT ]; then
                  APP_LIST_VISIBLE="$APP_LIST_VISIBLE- \`/wizard-ci $category/$app\`\n"
                else
                  APP_LIST_COLLAPSED="$APP_LIST_COLLAPSED- \`/wizard-ci $category/$app\`\n"
                fi
                APP_COUNT=$((APP_COUNT + 1))
              done
            fi
          done

          # Use heredoc for multiline outputs
          {
            echo "categories<<EOF"
            echo -e "$CATEGORY_LIST"
            echo "EOF"
          } >> $GITHUB_OUTPUT

          {
            echo "apps_visible<<EOF"
            echo -e "$APP_LIST_VISIBLE"
            echo "EOF"
          } >> $GITHUB_OUTPUT

          {
            echo "apps_collapsed<<EOF"
            echo -e "$APP_LIST_COLLAPSED"
            echo "EOF"
          } >> $GITHUB_OUTPUT

      - name: Post wizard-ci hint
        uses: actions/github-script@f28e40c7f34bde8b3046d885e986cb6290c5673b # v7.1.0
        env:
          CATEGORIES_OUTPUT: ${{ steps.fetch-apps.outputs.categories }}
          APPS_VISIBLE_OUTPUT: ${{ steps.fetch-apps.outputs.apps_visible }}
          APPS_COLLAPSED_OUTPUT: ${{ steps.fetch-apps.outputs.apps_collapsed }}
          PR_NUMBER: ${{ inputs.pr_number }}
        with:
          script: |
            const categories = process.env.CATEGORIES_OUTPUT || '';
            const appsVisible = process.env.APPS_VISIBLE_OUTPUT || '';
            const appsCollapsed = process.env.APPS_COLLAPSED_OUTPUT || '';
            const inputPrNumber = process.env.PR_NUMBER;

            const bodyParts = [
              '## 🧙 Wizard CI',
              '',
              'Run the Wizard CI and test your changes against [wizard-workbench](https://github.com/PostHog/wizard-workbench) example apps by replying with a GitHub comment using one of the following commands:',
              '',
              '**Test all apps:**',
              '- `/wizard-ci all`',
              '',
              '**Test all apps in a directory:**',
              categories.trim(),
              '',
              '**Test an individual app:**',
              appsVisible.trim()
            ];

            if (appsCollapsed.trim()) {
              bodyParts.push('');
              bodyParts.push('<details>');
              bodyParts.push('<summary>Show more apps</summary>');
              bodyParts.push('');
              bodyParts.push(appsCollapsed.trim());
              bodyParts.push('</details>');
            }

            bodyParts.push('');
            bodyParts.push('**Test against a wizard branch:**');
            bodyParts.push('- `/wizard-ci all wizard:my-branch`');
            bodyParts.push('');
            bodyParts.push('Add `wizard:<branch>` to any command above to pin the wizard branch. It defaults to `main`.');
            bodyParts.push('');
            bodyParts.push('Results will be posted here when complete.');

            const body = bodyParts.join('\n');

            const prNumber = context.eventName === 'workflow_dispatch'
              ? parseInt(inputPrNumber, 10)
              : context.payload.pull_request.number;

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
              body
            });

  # ============================================================================
  # HANDLE COMMAND: Parse /wizard-ci and trigger workflow
  # ============================================================================
  handle-command:
    if: |
      github.event_name == 'issue_comment' &&
      github.event.issue.pull_request &&
      contains(fromJSON('["OWNER", "MEMBER", "COLLABORATOR"]'), github.event.comment.author_association) &&
      startsWith(github.event.comment.body, '/wizard-ci')
    runs-on: ubuntu-latest
    steps:
      - name: Generate GitHub App token
        id: app-token
        uses: actions/create-github-app-token@d72941d797fd3113feb6b93fd0dec494b13a2547 # v1.12.0
        with:
          app-id: ${{ secrets.GH_APP_POSTHOG_WIZARD_CI_BOT_APP_ID }}
          private-key: ${{ secrets.GH_APP_POSTHOG_WIZARD_CI_BOT_PRIVATE_KEY }}
          owner: PostHog
          repositories: wizard-workbench,context-mill

      - name: Parse command and trigger
        uses: actions/github-script@f28e40c7f34bde8b3046d885e986cb6290c5673b # v7.1.0
        with:
          github-token: ${{ steps.app-token.outputs.token }}
          script: |
            // Get PR details first to check state
            const pr = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.payload.issue.number
            });

            // Only allow triggers on open PRs (including drafts)
            if (pr.data.state !== 'open') {
              console.log(`PR is ${pr.data.state}, skipping trigger`);
              return;
            }

            const comment = context.payload.comment.body;
            const match = comment.match(/\/wizard-ci\s+(\S+)/);
            const firstArg = match ? match[1] : 'all';

            // A reviewer can pin the companion repo with `wizard:<ref>`.
            // A lone pin is not an app name, so fall back to every app.
            const app = firstArg.startsWith('wizard:') ? 'all' : firstArg;

            // The ref arrives in a PR comment, so treat it as untrusted. Accept
            // git ref characters only. Reject traversal, a leading dash and a
            // trailing slash.
            const isPlausibleRef = (ref) =>
              ref.length <= 200 &&
              /^[A-Za-z0-9._\/-]+$/.test(ref) &&
              !ref.includes('..') &&
              !ref.startsWith('-') &&
              !ref.startsWith('/') &&
              !ref.endsWith('/');

            // Read the pin from the command line only, not from later prose.
            const companion = comment
              .split(/\r?\n/)[0]
              .match(/(?:^|\s)wizard:(\S+)/);
            const wizardRef = companion ? companion[1] : null;

            if (wizardRef && !isPlausibleRef(wizardRef)) {
              core.setFailed(
                'The wizard ref is not a valid git ref. ' +
                  'Use `/wizard-ci <app> wizard:<branch>`.'
              );
              return;
            }

            // React with rocket to show we're processing
            await github.rest.reactions.createForIssueComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              comment_id: context.payload.comment.id,
              content: 'rocket'
            });

            // Trigger wizard-ci on wizard-workbench
            await github.rest.repos.createDispatchEvent({
              owner: 'PostHog',
              repo: 'wizard-workbench',
              event_type: 'wizard-ci-trigger',
              client_payload: {
                app: app,
                source: 'context-mill-pr',
                source_repo: 'context-mill',
                source_pr_number: context.payload.issue.number,
                source_pr_url: pr.data.html_url,
                context_mill_ref: pr.data.head.ref,
                // Omit the key when unpinned. The workbench then uses `main`.
                ...(wizardRef ? { wizard_ref: wizardRef } : {}),
                notify_slack: 'false',
                notify_pr: 'true'
              }
            });

            const pinNote = wizardRef ? ` (wizard ref ${wizardRef})` : '';
            console.log(`Triggered wizard-ci for app: ${app}${pinNote}`);

import type { Route } from "./+types/api.auth.login";
import { getBurritoConsiderations } from "../lib/db";
import type { PostHogContext } from "../lib/posthog-middleware";

const users = new Map<string, { username: string }>();

export { users };

export async function action({ request, context }: Route.ActionArgs) {
  const body = await request.json();
  const { username, password } = body;

  if (!username || !password) {
    return Response.json({ error: 'Username and password required' }, { status: 400 });
  }

  let user = users.get(username);

  if (!user) {
    user = { username };
    users.set(username, user);
  }

  const posthog = (context as PostHogContext).posthog;
  if (posthog) {
    posthog.capture({ event: 'server_login' });
  }

  const burritoConsiderations = await getBurritoConsiderations(username);

  return Response.json({ 
    success: true, 
    user: { ...user, burritoConsiderations } 
  });
}

import { useServerPostHog } from '../../utils/posthog'
import { getOrCreateUser, users } from '../../utils/users'

export default defineEventHandler(async (event) => {
  const body = await readBody<{ username: string; password: string }>(event)
  const { username, password } = body || {}

  if (!username || !password) {
    throw createError({
      statusCode: 400,
      message: 'Username and password required',
    })
  }

  const user = getOrCreateUser(username)
  const isNewUser = !users.has(username)

  const sessionId = getHeader(event, 'x-posthog-session-id')
  const distinctId = getHeader(event, 'x-posthog-distinct-id')

  // Capture server-side login event
  const posthog = useServerPostHog()

  posthog.capture({
    distinctId: distinctId,
    event: 'server_login',
    properties: {
      $session_id: sessionId,
      username: username,
      isNewUser: isNewUser,
      source: 'api',
    },
  })

  // This handler is short-lived; flush so the enqueued event sends before it returns
  await posthog.flush()

  return {
    success: true,
    user,
  }
})

import { getOrCreateUser } from '~/server/utils/users'
import { PostHog } from 'posthog-node'
import { useRuntimeConfig } from '#imports'
import { getHeader } from 'h3'

export default defineEventHandler(async (event) => {
  if (event.node.req.method !== 'POST') {
    throw createError({
      statusCode: 405,
      statusMessage: 'Method Not Allowed'
    })
  }

  const body = await readBody(event)
  const { username, password } = body

  if (!username || !password) {
    throw createError({
      statusCode: 400,
      statusMessage: 'Username and password required'
    })
  }

  // Fake auth - just get or create user
  const user = getOrCreateUser(username)

  const runtimeConfig = useRuntimeConfig()

    // Relies on tracing_headers being set in the client-side SDK
  const sessionId = getHeader(event, 'x-posthog-session-id')
  const distinctId = getHeader(event, 'x-posthog-distinct-id')

  const posthog = new PostHog(
    runtimeConfig.public.posthog.publicKey,
    { 
      host: runtimeConfig.public.posthog.host, 
    }
  )

  await posthog.withContext(
    { sessionId: sessionId ?? undefined, distinctId: distinctId ?? undefined },
    async () => {
      posthog.capture({
        event: 'server_login',
        distinctId: distinctId ?? username,
      })
    }
  )

  // Always shutdown to ensure all events are flushed
  await posthog.shutdown()

  return {
    success: true,
    user: { ...user }
  }
})

import type { NextApiRequest, NextApiResponse } from 'next';
import { getPostHogClient } from '@/lib/posthog-server';

const users = new Map<string, { username: string; burritoConsiderations: number }>();

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: 'Username and password required' });
  }

  let user = users.get(username);
  const isNewUser = !user;

  if (!user) {
    user = { username, burritoConsiderations: 0 };
    users.set(username, user);
  }

  // Capture server-side login event
  const posthog = getPostHogClient();
  posthog.capture({
    distinctId: username,
    event: 'server_login',
    properties: {
      isNewUser: isNewUser,
      source: 'api'
    }
  });

  // Identify user on server side
  posthog.identify({
    distinctId: username,
    properties: {
      username: username,
      createdAt: isNewUser ? new Date().toISOString() : undefined
    }
  });

  // This handler is short-lived; flush so the enqueued events send before it returns
  await posthog.flush();

  return res.status(200).json({ success: true, user });
}

import type { APIRoute } from "astro";
