"""Authentication dependencies for FastAPI."""

from typing import Annotated, Optional

from fastapi import Cookie, Depends, HTTPException, status
from itsdangerous import BadSignature, URLSafeSerializer
from sqlalchemy.orm import Session

from app.config import get_settings
from app.database import get_db
from app.models import User

settings = get_settings()
serializer = URLSafeSerializer(settings.secret_key)


def get_session_user_id(session_token: Annotated[Optional[str], Cookie()] = None) -> Optional[int]:
    """Extract user ID from session cookie."""
    if not session_token:
        return None
    try:
        data = serializer.loads(session_token)
        return data.get("user_id")
    except BadSignature:
        return None


def get_current_user(
    db: Annotated[Session, Depends(get_db)],
    user_id: Annotated[Optional[int], Depends(get_session_user_id)],
) -> Optional[User]:
    """Get the current authenticated user, or None if not authenticated."""
    if user_id is None:
        return None
    return User.get_by_id(db, user_id)


def require_auth(
    current_user: Annotated[Optional[User], Depends(get_current_user)],
) -> User:
    """Require authentication - raises 401 if not authenticated."""
    if current_user is None:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Authentication required",
        )
    return current_user


def create_session_token(user_id: int) -> str:
    """Create a signed session token for the user."""
    return serializer.dumps({"user_id": user_id})


# Type aliases for cleaner dependency injection
CurrentUser = Annotated[Optional[User], Depends(get_current_user)]
RequiredUser = Annotated[User, Depends(require_auth)]
DbSession = Annotated[Session, Depends(get_db)]

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdirSync, writeFileSync, mkdtempSync, rmSync, readFileSync, existsSync } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';

import { buildAgents } from '../agent-generator.js';

const prompt = (frontmatter) => `---\n${frontmatter}\n---\n\n## Goal\n\nDo the thing.\n`;

describe('buildAgents flow frontmatter', () => {
    let tmpDir;
    let configDir;
    let distDir;

    beforeEach(() => {
        tmpDir = mkdtempSync(join(tmpdir(), 'agents-test-'));
        configDir = join(tmpDir, 'context');
        distDir = join(tmpDir, 'dist');
        mkdirSync(join(configDir, 'agents', 'my-flow'), { recursive: true });
    });

    afterEach(() => rmSync(tmpDir, { recursive: true, force: true }));

    it('builds a prompt whose flow matches its folder', () => {
        writeFileSync(
            join(configDir, 'agents', 'my-flow', 'task.md'),
            prompt('type: task\nflow: my-flow'),
        );
        const { count } = buildAgents({ configDir, distDir, baseUrl: 'http://x' });
        expect(count).toBe(1);
        const menu = JSON.parse(readFileSync(join(distDir, 'agents', 'agent-menu.json'), 'utf8'));
        expect(menu.agents).toEqual([
            { id: 'task', flow: 'my-flow', downloadUrl: 'http://x/agents-my-flow-task.md' },
        ]);
    });

    it('rejects a prompt missing the flow key — consumers filter by it', () => {
        writeFileSync(
            join(configDir, 'agents', 'my-flow', 'task.md'),
            prompt('type: task'),
        );
        expect(() => buildAgents({ configDir, distDir, baseUrl: 'http://x' })).toThrow(
            /missing the "flow:" frontmatter key/,
        );
    });

    it('rejects a prompt whose flow contradicts its folder', () => {
        writeFileSync(
            join(configDir, 'agents', 'my-flow', 'task.md'),
            prompt('type: task\nflow: other-flow'),
        );
        expect(() => buildAgents({ configDir, distDir, baseUrl: 'http://x' })).toThrow(
            /declares flow "other-flow"/,
        );
    });

    it('rejects a runner-seeded task in a flow with no sink to wait for it', () => {
        writeFileSync(
            join(configDir, 'agents', 'my-flow', 'warehouse.md'),
            prompt('type: warehouse\nflow: my-flow\nrunnerSeeded: true'),
        );
        writeFileSync(
            join(configDir, 'agents', 'my-flow', 'report.md'),
            prompt('type: report\nflow: my-flow'),
        );
        expect(() => buildAgents({ configDir, distDir, baseUrl: 'http://x' })).toThrow(
            /runner-seeded warehouse but no agent marked "sink: true"/,
        );
    });

    it('accepts a runner-seeded task once a sink waits for it', () => {
        writeFileSync(
            join(configDir, 'agents', 'my-flow', 'warehouse.md'),
            prompt('type: warehouse\nflow: my-flow\nrunnerSeeded: true'),
        );
        writeFileSync(
            join(configDir, 'agents', 'my-flow', 'report.md'),
            prompt('type: report\nflow: my-flow\nsink: true'),
        );
        expect(buildAgents({ configDir, distDir, baseUrl: 'http://x' }).count).toBe(2);
    });

    it('leaves a flow with no runner-seeded task alone', () => {
        writeFileSync(
            join(configDir, 'agents', 'my-flow', 'task.md'),
            prompt('type: task\nflow: my-flow'),
        );
        expect(buildAgents({ configDir, distDir, baseUrl: 'http://x' }).count).toBe(1);
    });

    it('still ignores README.md files at both levels', () => {
        writeFileSync(join(configDir, 'agents', 'README.md'), '# docs');
        writeFileSync(join(configDir, 'agents', 'my-flow', 'README.md'), '# docs');
        writeFileSync(
            join(configDir, 'agents', 'my-flow', 'task.md'),
            prompt('type: task\nflow: my-flow'),
        );
        const { count } = buildAgents({ configDir, distDir, baseUrl: 'http://x' });
        expect(count).toBe(1);
        expect(existsSync(join(distDir, 'agents', 'my-flow', 'README.md'))).toBe(false);
    });
});

import fs from 'fs';
import path from 'path';
import { runInNewContext } from 'vm';
import { describe, expect, it } from 'vitest';
import {
    EMBEDDED_BROWSER_SNIPPETS,
    generateBrowserSnippet,
    renderEmbeddedBrowserSnippet,
} from '../../generate-browser-snippets.js';

const REPO_ROOT = path.join(import.meta.dirname, '..', '..', '..');

function runSnippetWithReadOnlyArrayToString(target = EMBEDDED_BROWSER_SNIPPETS[0]) {
    const insertedScripts = [];
    const context = {
        document: {
            createElement: () => ({}),
            getElementsByTagName: () => [{
                parentNode: {
                    insertBefore: script => insertedScripts.push(script),
                },
            }],
        },
        window: {},
    };

    runInNewContext(
        `'use strict';Object.defineProperty(Array.prototype,'toString',{writable:false});${generateBrowserSnippet(target)}`,
        context,
    );
    context.window.posthog.init('phc_test', { api_host: 'https://us.i.posthog.com' });

    return { insertedScripts, posthog: context.window.posthog };
}

describe('embedded PostHog browser snippet', () => {
    it('keeps every embedded copy in sync with the generator', () => {
        for (const target of EMBEDDED_BROWSER_SNIPPETS) {
            const content = fs.readFileSync(path.join(REPO_ROOT, target.file), 'utf8');
            expect(renderEmbeddedBrowserSnippet(content, target), target.file).toBe(content);
        }
    });

    it.each(EMBEDDED_BROWSER_SNIPPETS)(
        'initializes $file when Array.prototype.toString is read-only',
        target => {
            const { insertedScripts, posthog } = runSnippetWithReadOnlyArrayToString(target);

            expect(insertedScripts).toHaveLength(1);
            expect(posthog._i).toEqual([
                ['phc_test', { api_host: 'https://us.i.posthog.com' }, 'posthog'],
            ]);
            expect(posthog.toString()).toBe('posthog (stub)');
            expect(posthog.people.toString()).toBe('posthog.people (stub)');
        },
    );

    it('preserves the toString property behavior', () => {
        const { posthog } = runSnippetWithReadOnlyArrayToString();

        for (const stub of [posthog, posthog.people]) {
            expect(Object.getOwnPropertyDescriptor(stub, 'toString')).toMatchObject({
                configurable: true,
                enumerable: true,
                writable: true,
            });
        }
    });
});

import { describe, expect, it } from 'vitest';
